/** Collapse padded Excel tables and repeated coach rows.
 *  Same person on two teams stays two rows. Blank table padding does not.
 */

import { norm } from "../model";
import { normalizeBracket } from "../planning";

export interface CoachRow {
  name: string;
  phone: string;
  email: string;
  age: string;
  role: string;
  team: string;
  comments: string;
}

export interface DedupeStats {
  emptySkipped: number;
  headerRepeats: number;
  duplicatesDropped: number;
  merged: number;
  kept: number;
}

export interface DedupeResult {
  rows: CoachRow[];
  stats: DedupeStats;
}

export function isHeaderRepeat(name: string): boolean {
  const n = norm(name);
  return n === "name" || n === "team name" || n === "age group";
}

function roleKind(role: string): "assistant" | "head" | "other" | "" {
  const r = role.trim();
  if (!r) return "";
  if (/assistant|asst\.?/i.test(r)) return "assistant";
  if (/head|coach/i.test(r)) return "head";
  return "other";
}

function richness(row: CoachRow): number {
  return [row.phone, row.email, row.role, row.team, row.comments].filter((s) => s.trim()).length;
}

function takeRicher(a: CoachRow, b: CoachRow): CoachRow {
  const pick = richness(b) > richness(a) ? b : a;
  const other = pick === a ? b : a;
  return {
    name: pick.name || other.name,
    phone: pick.phone || other.phone,
    email: pick.email || other.email,
    age: pick.age || other.age,
    role: pick.role || other.role,
    team: pick.team || other.team,
    comments: pick.comments || other.comments,
  };
}

export function identityKey(row: CoachRow): string {
  return [norm(row.name), norm(normalizeBracket(row.age) || row.age), norm(row.team), roleKind(row.role) || norm(row.role)].join("|");
}

function softKey(row: CoachRow): string {
  return [norm(row.name), norm(normalizeBracket(row.age) || row.age), norm(row.team)].join("|");
}

/** Drop blank table padding and exact/near-duplicate coach rows. Merge when one copy is richer. */
export function dedupeCoachRows(input: CoachRow[]): DedupeResult {
  const stats: DedupeStats = { emptySkipped: 0, headerRepeats: 0, duplicatesDropped: 0, merged: 0, kept: 0 };
  const kept: CoachRow[] = [];
  const byId = new Map<string, number>();
  const bySoft = new Map<string, number[]>();

  const indexSoft = (row: CoachRow, idx: number) => {
    const k = softKey(row);
    const list = bySoft.get(k) || [];
    list.push(idx);
    bySoft.set(k, list);
  };

  for (const raw of input) {
    if (!raw.name.trim() && !raw.team.trim() && !raw.age.trim()) {
      stats.emptySkipped += 1;
      continue;
    }
    if (raw.name && isHeaderRepeat(raw.name)) {
      stats.headerRepeats += 1;
      continue;
    }
    const id = identityKey(raw);
    const exact = byId.get(id);
    if (exact != null) {
      kept[exact] = takeRicher(kept[exact], raw);
      stats.duplicatesDropped += 1;
      continue;
    }
    const kind = roleKind(raw.role);
    if (kind === "") {
      const siblings = bySoft.get(softKey(raw)) || [];
      const partner = siblings.find((i) => {
        const k = roleKind(kept[i].role);
        return k === "head" || k === "assistant";
      });
      if (partner != null) {
        kept[partner] = takeRicher(kept[partner], raw);
        stats.merged += 1;
        continue;
      }
    } else {
      const siblings = bySoft.get(softKey(raw)) || [];
      const emptyRole = siblings.find((i) => roleKind(kept[i].role) === "");
      if (emptyRole != null) {
        const oldId = identityKey(kept[emptyRole]);
        kept[emptyRole] = takeRicher(kept[emptyRole], raw);
        byId.delete(oldId);
        byId.set(identityKey(kept[emptyRole]), emptyRole);
        stats.merged += 1;
        continue;
      }
    }
    const idx = kept.length;
    kept.push({ ...raw });
    byId.set(id, idx);
    indexSoft(raw, idx);
  }
  stats.kept = kept.length;
  return { rows: kept, stats };
}

export function describeDedupe(stats: DedupeStats): string {
  const bits: string[] = [];
  if (stats.emptySkipped) bits.push(`skipped ${stats.emptySkipped} blank table row${stats.emptySkipped === 1 ? "" : "s"}`);
  if (stats.headerRepeats) bits.push(`ignored ${stats.headerRepeats} repeated header${stats.headerRepeats === 1 ? "" : "s"}`);
  if (stats.duplicatesDropped) bits.push(`dropped ${stats.duplicatesDropped} duplicate coach row${stats.duplicatesDropped === 1 ? "" : "s"}`);
  if (stats.merged) bits.push(`merged ${stats.merged} overlapping row${stats.merged === 1 ? "" : "s"}`);
  if (!bits.length) return "No duplicate rows.";
  return bits.join("; ") + ".";
}
